<div class="receipt-summary"><div class="receipt-total">{{ __('Received') }}: INR {{ number_format($payment->amount,2) }}</div><p>{{ \App\Services\NumberToWordsService::convert($payment->amount) }}</p><p>{{ $payment->notes }}</p><p class="receipt-note">{{ __('This receipt records a payment entered by the business. It does not independently verify bank settlement. Original party and invoice details are retained from the time of recording.') }}</p>
